  return { state: 'ok', headers, pkgIdx, rows, scanned: all.length, page: pm ? +pm[1] : 0, pages: pm ? +pm[2] : 0, items: pm ? +pm[3] : 0, firstKey: all[0] ? all[0].join('|').slice(0, 120) : '' };
